"""Registrar leituras e inspeção visual do lote B2-04 (registro 122)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');first=load(A/'imagens-inspecionadas-primeira-prova-visual.json');N=len(m['paginas']);assert N==17
same={i for i in range(1,N+1) if first[str(i)]==sha(A/f'pagina-{i:02}.png')};again=set(range(1,N+1))-same
assert same=={1,4,5,9,10,12,14,15},same
notes={1:'Abertura da Doma e quadro "No confronto / Depois da Doma" em largura inteira; aquisição e TR legíveis.',2:'Ficha da entidade em quadro largo; Pancada, manobras, talentos e começo de Condução urgente em colunas.',3:'Condução urgente, montagem e exemplo inteiros; Dobrar o sino com primeiro turno, liberação, exposição e montagem.',4:'Recuperar e comandar, com religar corrigido para 4 PE; acompanhamento e remissões. Espaço de fechamento do caso.',5:'Abertura do ensaio, preparo da mesa e mapa vetorial com legenda, sem margem excedente.',6:'Zona, quadro dos três personagens e capacidades em colunas; iniciativa.',7:'Rodadas 1 e 2 do primeiro exemplo; títulos e passos legíveis.',8:'Rodada 3 com quadro de estado; começo do segundo exemplo, queda de Mei e Insistir.',9:'Socorro, quadro de estado após o socorro, Aguentar e observações. Espaço de fechamento do caso.',10:'Abertura de Ren e Sora e quadro largo das fichas, com linhas inteiras.',11:'Recursos comuns, Ren, espada e Fenda em marcha.',12:'Sora, Fio, Remendo e prioridades; lista de Fio legível.',13:'Quadro de Integridade e derrota. Espaço de fechamento do caso.',14:'Abertura do confronto, tabela de posições e mapa vetorial novo em largura inteira, seguido das informações a mostrar.',15:'Perfis, iniciativas e rodadas 1–2.',16:'Fim da rodada 2, rodada 3 e quadro final do confronto.',17:'Quadro das chances em largura inteira; análise do apoio em colunas, sem corte.'}
save('revisao-final.json',{'registro':122,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões, clareza e a correção documentada de religar.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura integral das dezessete páginas da primeira prova completa e pente fino, incluindo frases da primeira passagem.'}],'paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':sha(A/f'pagina-{i:02}.png'),'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i in again else 'Inspeção direta na primeira prova; imagem final idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Espaços de fechamento nas páginas 4, 9 e 13 serão reavaliados na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s072':[1,4],'s073':[5,9],'s075':[10,13],'s076':[14,17]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova_1':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':122,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':122,'lote':'B2-04','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':27,'casos_pendentes':32,'lotes_pendentes':8,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B2-05','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'revistas_apos_ajuste':sorted(again),'identicas':sorted(same),'registros':len(changes),'casos':4},ensure_ascii=False))
